package com.ryanjei.orushio.pve.map;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.application.*;import com.ryanjei.orushio.pve.domain.*;import com.ryanjei.orushio.pve.persistence.ActiveSessionRepository;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SetupMarkerAdministrationTest{@TempDir Path temp;
 @Test void 専用Blockは管理者SessionMapへ固定し保存できる()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID(),other=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");f.service.issueSetupMarker(admin,SetupMarkerType.NORMAL_ENEMY_SPAWN);assertEquals(admin,f.world.recipient);assertEquals(SetupMarkerType.NORMAL_ENEMY_SPAWN,f.world.token.markerType());assertThrows(SecurityException.class,()->f.service.recordSetupMarker(other,f.world.token,new BlockPoint(1,64,1,0,0)));var old=new MapWorldGateway.SetupMarkerToken(UUID.randomUUID(),SetupMarkerType.NORMAL_ENEMY_SPAWN,UUID.randomUUID().toString(),"map-a",admin);assertThrows(SecurityException.class,()->f.service.recordSetupMarker(admin,old,new BlockPoint(1,64,1,0,0)));f.service.recordSetupMarker(admin,f.world.token,new BlockPoint(1,64,1,0,0));UUID id=f.world.token.markerId();f.service.setSetupMarkerEnabled(admin,id,false);assertFalse(f.service.setup().setupMarkerTypes().stream().flatMap(type->type.markers().stream()).findFirst().orElseThrow().enabled());f.service.saveSetup(f.games.current().sessionId().toString());assertEquals(id,f.profiles.find(new MapProfileId("map-a")).orElseThrow().setupMarkers().getFirst().markerId());}
 @Test void 同一座標拒否しワープ削除と破棄をDraft内で行う()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");f.service.issueSetupMarker(admin,SetupMarkerType.WEAPON_SHOP);BlockPoint point=new BlockPoint(2,64,2,0,0);f.service.recordSetupMarker(admin,f.world.token,point);UUID first=f.world.token.markerId();f.service.teleportSetupMarker(admin,first);assertEquals(point,f.world.teleported);f.service.issueSetupMarker(admin,SetupMarkerType.ARMOR_SHOP);assertThrows(IllegalArgumentException.class,()->f.service.recordSetupMarker(admin,f.world.token,point));f.service.removeSetupMarker(admin,first);assertTrue(f.service.setup().setupMarkerTypes().stream().flatMap(type->type.markers().stream()).findAny().isEmpty());f.service.discardSetup(f.games.current().sessionId().toString());assertTrue(f.profiles.find(new MapProfileId("map-a")).orElseThrow().setupMarkers().isEmpty());}
 @Test void 現在Draft所有SetupWorldでは登録し別setupWorldでは登録しない()throws Exception{Fixture f=fixture();UUID admin=UUID.randomUUID();f.service.startSetup("map-a",admin,"IDLE");f.service.issueSetupMarker(admin,SetupMarkerType.FARM_RESPAWN);String current=f.world.owned.worldName(),other="orushio_setup_別の所有World";assertTrue(f.service.ownsSetupWorld(admin,current));if(f.service.ownsSetupWorld(admin,current))f.service.recordSetupMarker(admin,f.world.token,new BlockPoint(3,64,3,0,0));assertEquals(1,f.service.setup().setupMarkerTypes().stream().flatMap(type->type.markers().stream()).count());assertFalse(f.service.ownsSetupWorld(admin,other));if(f.service.ownsSetupWorld(admin,other))f.service.recordSetupMarker(admin,f.world.token,new BlockPoint(4,64,4,0,0));assertEquals(1,f.service.setup().setupMarkerTypes().stream().flatMap(type->type.markers().stream()).count());assertThrows(SecurityException.class,()->f.service.ownsSetupWorld(UUID.randomUUID(),current));}
 private Fixture fixture()throws Exception{Path maps=temp.resolve("maps"),worldRoot=temp.resolve("worlds"),template=maps.resolve("map-a/template");Files.createDirectories(template);Files.writeString(template.resolve("level.dat"),"x");Files.writeString(maps.resolve("map-a/.orushio-map-owner"),"map-a");Profiles profiles=new Profiles();profiles.save(MapProfileTest.empty("map-a"));Session session=new Session();DefaultGameApplicationService games=new DefaultGameApplicationService(session);World world=new World();var service=new DefaultMapAdministrationService(maps,profiles,new SafeWorldZipImporter(maps,SafeWorldZipImporter.Limits.defaults()),new TemporaryWorldManager(maps,worldRoot),world,games,new MapSelectionService(new Random(1)));return new Fixture(service,profiles,games,world);}
 record Fixture(DefaultMapAdministrationService service,Profiles profiles,DefaultGameApplicationService games,World world){}static final class Profiles implements MapProfileRepository{final Map<MapProfileId,MapProfile>values=new HashMap<>();public List<MapProfile>findAll(){return List.copyOf(values.values());}public Optional<MapProfile>find(MapProfileId id){return Optional.ofNullable(values.get(id));}public void save(MapProfile value){values.put(value.mapId(),value);}public void delete(MapProfileId id){values.remove(id);}}static final class Session implements ActiveSessionRepository{GameSession value;public Optional<GameSession>load(){return Optional.ofNullable(value);}public void save(GameSession value){this.value=value;}}static final class World implements MapWorldGateway{TemporaryWorldManager.OwnedWorld owned;UUID recipient;SetupMarkerToken token;BlockPoint teleported;public void loadForSetup(TemporaryWorldManager.OwnedWorld world,UUID admin){owned=world;}public void unload(TemporaryWorldManager.OwnedWorld world){}public void giveSetupMarkerBlock(TemporaryWorldManager.OwnedWorld world,UUID admin,SetupMarkerToken token){assertEquals(owned,world);recipient=admin;this.token=token;}public void teleportSetupAdministrator(TemporaryWorldManager.OwnedWorld world,UUID admin,BlockPoint point){assertEquals(owned,world);teleported=point;}}
}
